  outline-offset: 2px;
}

/* ============================================================
   Site header
   ============================================================ */
.site-header {
  background: #fff;
  border-bottom: 1px solid #e4e7ef;
  padding: 0 1.5rem;
}

.site-header__inner {
  max-width: 640px;
  margin: 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 0.625rem;
}

.site-header__logo {
  font-size: 1.25rem;
  color: #2563eb;
}

.site-header__brand {
  font-weight: 700;
  font-size: 1rem;
  letter-spacing: -0.01em;
  color: #1a1d23;
}

/* ============================================================
   Page layout
   ============================================================ */
.page-wrapper {
  max-width: 640px;
  margin: 0 auto;
  padding: 2.5rem 1rem 4rem;
}

/* ============================================================
   Form card
   ============================================================ */
.form-card {
  background: #fff;
  border-radius: 12px;
  box-shadow: 0 1px 3px rgba(0,0,0,.08), 0 4px 16px rgba(0,0,0,.06);
  padding: 2rem 2rem 2.5rem;
}

.form-card__header {
  margin-bottom: 1.5rem;
}

.form-card__title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #1a1d23;
  line-height: 1.25;
}

.form-card__subtitle {
  margin-top: 0.375rem;
  color: #5a6070;
  font-size: 0.9375rem;
}

/* ============================================================
   Required legend
   ============================================================ */
.required-legend {
  font-size: 0.8125rem;
  color: #5a6070;
  margin-bottom: 1.5rem;
}

.required-legend span[aria-hidden] {
  color: #dc2626;
  font-weight: 700;
  margin-right: 0.125rem;
}

/* ============================================================
   Status / alert message banners
   ============================================================ */
.message {
  border-radius: 8px;
  padding: 0.875rem 1rem;
  font-size: 0.9375rem;
  margin-bottom: 1.5rem;
}

.message--error {
  background: #fef2f2;
  border: 1px solid #fca5a5;
  color: #991b1b;
}

.message--success {
  background: #f0fdf4;
  border: 1px solid #86efac;
  color: #166534;
}

.message[hidden] {
  display: none;
}

/* ============================================================
   Form fields
   ============================================================ */
#contact-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: #1a1d23;
}

label span[aria-hidden] {
  color: #dc2626;
  margin-left: 0.125rem;
}

.optional-label {
  font-weight: 400;
  color: #5a6070;
  font-size: 0.875rem;
}

input {
  width: 100%;
  padding: 0.625rem 0.875rem;
  border: 1.5px solid #d1d5e0;
  border-radius: 8px;
  font-size: 1rem;
  font-family: inherit;
  color: #1a1d23;
  background: #fff;
  transition: border-color 0.15s, box-shadow 0.15s;
  appearance: none;
}

input:hover {
  border-color: #9ca3af;
}

input:focus {
  outline: none;
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
}

input[aria-invalid="true"] {
  border-color: #dc2626;
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.2);
}

/* ============================================================
   Help & error text
   ============================================================ */
.field-help {
  font-size: 0.8125rem;
  color: #5a6070;
  line-height: 1.5;
}

.field-error {
  font-size: 0.8125rem;
  color: #dc2626;
  font-weight: 500;
  line-height: 1.4;
}

.field-error[hidden] {
  display: none;
}

/* ============================================================
   Submit button
   ============================================================ */
.btn-submit {
  margin-top: 0.5rem;
  align-self: flex-start;
  padding: 0.6875rem 1.75rem;
  background: #2563eb;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  box-shadow: 0 1px 3px rgba(37, 99, 235, 0.4);
}

.btn-submit:hover {
  background: #1d4ed8;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.4);
}

.btn-submit:active {
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid #fbbf24;
  outline-offset: 2px;
}

/* ============================================================
   Forced colors (Windows High Contrast)
   ============================================================ */
@media (forced-colors: active) {
  input {
    border: 2px solid ButtonText;
  }

  input:focus {
    outline: 3px solid Highlight;
    box-shadow: none;
  }

  .btn-submit {
    border: 2px solid ButtonText;
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
  }

  .field-error {
    color: LinkText;
  }
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
    animation: none !important;
  }
}

/* ============================================================
   Responsive / reflow (≥320 px)
   ============================================================ */
@media (max-width: 480px) {
  .form-card {
    padding: 1.25rem 1rem 1.75rem;
    border-radius: 8px;
  }

  .btn-submit {
    width: 100%;
    text-align: center;
  }
}
