AssistantMessageToolRequest(name='create', tool_call_id='tooluse_noHpMWsxvI3zH9xGAL9NEQ', arguments={'file_text': '(function () {
  "use strict";

  const form = document.getElementById("contact-form");
  const errorSummary = document.getElementById("form-error-summary");
  const successBanner = document.getElementById("form-success");

  // Field descriptors used for validation and messaging
  const fields = [
    {
      input: document.getElementById("full-name"),
      errorEl: document.getElementById("full-name-error"),
      label: "Full name",
      validate(input) {
        return input.value.trim().length > 0;
      },
    },
    {
      input: document.getElementById("email"),
      errorEl: document.getElementById("email-error"),
      label: "Email address",
      validate(input) {
        // Basic structural check; browser type="email" handles deeper validation
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.value.trim());
      },
    },
    {
      input: document.getElementById("phone"),
      errorEl: document.getElementById("phone-error"),
      label: "Phone number",
      optional: true,
      validate(input) {
        const val = input.value.trim();
        if (!val) return true; // optional — blank is valid
        // Allow digits, spaces, parentheses, hyphens, plus sign
        return /^[+\d][\d\s\-().]{6,19}$/.test(val);
      },
    },
  ];

  /** Show an error state on a single field */
  function markInvalid(field) {
    field.input.setAttribute("aria-invalid", "true");
    field.errorEl.hidden = false;
  }

  /** Clear error state on a single field */
  function markValid(field) {
    field.input.removeAttribute("aria-invalid");
    field.errorEl.hidden = true;
  }

  /** Clear the summary and success banners */
  function clearBanners() {
    errorSummary.hidden = true;
    errorSummary.textContent = "";
    successBanner.hidden = true;
    successBanner.textContent = "";
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    clearBanners();

    const invalidFields = [];

    fields.forEach(function (field) {
      if (field.validate(field.input)) {
        markValid(field);
      } else {
        markInvalid(field);
        invalidFields.push(field);
      }
    });

    if (invalidFields.length > 0) {
      // Build an error summary and announce it via role="alert"
      const count = invalidFields.length;
      const noun = count === 1 ? "error" : "errors";
      errorSummary.textContent =
        count +
        " " +
        noun +
        " found. Please correct: " +
        invalidFields.map(function (f) { return f.label; }).join(", ") +
        ".";
      errorSummary.hidden = false;

      // Move focus to the first invalid control
      invalidFields[0].input.focus();
      return;
    }

    // All fields valid — simulate a successful submission
    form.reset();
    successBanner.textContent =
      "Your message has been sent. We\u2019ll get back to you within one business day.";
    successBanner.hidden = false;
    successBanner.scrollIntoView({ behavior: "smooth", block: "nearest" });
  });

  // Revalidate a field on blur only after the user has interacted with it
  fields.forEach(function (field) {
    field.input.addEventListener("blur", function () {
      if (!field.input.dataset.touched) return;
      if (field.validate(field.input)) {
        markValid(field);
      } else {
        markInvalid(field);
      }
    });

    field.input.addEventListener("input", function () {
      field.input.dataset.touched = "true";
      // Clear error eagerly once user starts fixing the field
      if (field.input.getAttribute("aria-invalid") === "true" && field.validate(field.input)) {
        markValid(field);
      }
    });
  });
})();
